The log-file append and the metadata fetch are left out. This node's world holds only `aap:caps/state-read`. There is no filesystem or HTTP capability to import, and adding one would widen the node's authority beyond its declared signature. If operations needs them, the graph would have to grant those capabilities, for example `http-client` and a log sink.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{run-info, subscription-list};

    import aap:caps/state-read@0.1.0;

    export run: func(info: run-info) -> subscription-list;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let urls = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(|l| l.trim())
                .filter(|l| !l.is_empty())
                .map(|l| l.to_string())
                .collect(),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
